38	    /// To call when visiting a source snippet, where bindings are defined.
39	    pub(crate) fn visit_js_source_snippet(&mut self, root: &AnyJsRoot) {
40	        let preorder = root.syntax().preorder();
41	
42	        for event in preorder {
43	            match event {
44	                WalkEvent::Enter(node) => {
45	                    if let Some(module_item) = JsModuleItemList::cast_ref(&node) {
46	                        self.visit_module_item_list(module_item);
47	                    } else if let Some(expr) = JsCallExpression::cast_ref(&node) {
48	                        self.visit_define_props_call(&expr);
49	                    }
50	                }
51	                WalkEvent::Leave(_) => {}
52	            }
53	        }
54	    }
55	
56	    fn visit_module_item_list(&mut self, list: JsModuleItemList) {
57	        for item in list {
58	            match item {
59	                AnyJsModuleItem::AnyJsStatement(statement) => match statement {
60	                    AnyJsStatement::JsVariableStatement(variable_statement) => {
61	                        self.visit_js_variable_statement(variable_statement.clone());
62	                    }
63	                    AnyJsStatement::JsExpressionStatement(expr_statement) => {
64	                        self.visit_js_expression_statement(expr_statement.clone());
65	                    }
66	                    AnyJsStatement::JsFunctionDeclaration(decl) => {
67	                        self.register_js_binding(decl.id());
68	                    }
69	                    AnyJsStatement::JsClassDeclaration(decl) => {
70	                        self.register_js_binding(decl.id());
71	                    }
72	                    AnyJsStatement::TsEnumDeclaration(decl) => {
73	                        self.register_js_binding(decl.id());
74	                    }
75	                    AnyJsStatement::TsInterfaceDeclaration(decl) => {
76	                        self.register_ts_identifier_binding(decl.id());
77	                    }
78	                    AnyJsStatement::TsTypeAliasDeclaration(decl) => {
79	                        self.register_ts_identifier_binding(decl.binding_identifier());
80	                    }
81	                    AnyJsStatement::TsDeclareFunctionDeclaration(decl) => {
82	                        self.register_js_binding(decl.id());
83	                    }
84	                    _ => {}
85	                },
86	                AnyJsModuleItem::JsExport(export) => {
87	                    self.visit_js_export(export);
88	                }
89	                AnyJsModuleItem::JsImport(import) => {
