37	    /// Visit a non-source snippet to track value references
38	    pub(crate) fn visit_non_source_snippet(&mut self, root: &AnyJsRoot) {
39	        let preorder = root.syntax().preorder();
40	
41	        for event in preorder {
42	            match event {
43	                WalkEvent::Enter(node) => {
44	                    if let Some(reference) = JsReferenceIdentifier::cast_ref(&node) {
45	                        self.visit_reference_identifier(reference);
46	                    } else if let Some(member) = JsStaticMemberExpression::cast_ref(&node) {
47	                        self.visit_static_member_expression(member);
48	                    }
49	                }
50	                WalkEvent::Leave(_) => {}
51	            }
52	        }
53	    }
