702	        &self,
703	        path: &BiomePath,
704	        source: &DocumentFileSource,
705	        root: &AnyParse,
706	        cache: &mut NodeCache,
707	        settings: &SettingsWithEditor,
708	        builder: &mut EmbeddedBuilder,
709	    ) -> Result<Vec<AnyEmbeddedSnippet>, WorkspaceError> {
710	        let mut embedded_nodes = Vec::new();
711	        let capabilities = self.get_file_capabilities(
712	            path,
713	            settings.as_ref().experimental_full_html_support_enabled(),
714	        );
715	        let Some(parse_embedded_nodes) = capabilities.parser.parse_embedded_nodes else {
716	            return Ok(Default::default());
717	        };
718	        let result = parse_embedded_nodes(root, path, source, settings, cache, builder);
719	
720	        for (mut content, file_source) in result.nodes {
721	            let index = self.insert_source(file_source);
